import{_ as u,C as m,o as n,c as d,a3 as i,b as l,w as e,a as t,E as s,a4 as o}from"./chunks/framework.BvvarXmc.js";const g="/screenshots/manage-users.png",x=JSON.parse('{"title":"Manajemen User (Daftar Pengguna)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-sistem/manage-users.md","filePath":"panduan-sistem/manage-users.md","lastUpdated":null}'),k={name:"panduan-sistem/manage-users.md"};function p(h,a,c,b,f,A){const r=m("Mermaid");return n(),d("div",null,[a[2]||(a[2]=i('<h1 id="manajemen-user-daftar-pengguna" tabindex="-1">Manajemen User (Daftar Pengguna) <a class="header-anchor" href="#manajemen-user-daftar-pengguna" aria-label="Permalink to &quot;Manajemen User (Daftar Pengguna)&quot;">​</a></h1><p>Menu <strong>Manajemen User</strong> digunakan oleh Administrator Utama untuk mengontrol seluruh akun yang memiliki hak akses ke dalam aplikasi Super Schools, termasuk akun Guru, Tenaga Kependidikan, Tata Usaha, Kasir Kantin, hingga Wali Kelas.</p><hr><h2 id="tampilan-antarmuka-manajemen-user" tabindex="-1">Tampilan Antarmuka Manajemen User <a class="header-anchor" href="#tampilan-antarmuka-manajemen-user" aria-label="Permalink to &quot;Tampilan Antarmuka Manajemen User&quot;">​</a></h2><p><img src="'+g+'" alt="Manajemen User"></p><hr><h2 id="_1-pencarian-filter-cepat-pengguna" tabindex="-1">1. Pencarian &amp; Filter Cepat Pengguna <a class="header-anchor" href="#_1-pencarian-filter-cepat-pengguna" aria-label="Permalink to &quot;1. Pencarian &amp; Filter Cepat Pengguna&quot;">​</a></h2><p>Di atas tabel daftar pengguna, tersedia alat filter untuk menemukan akun secara cepat:</p><ul><li><strong>Kolom Pencarian (<code>Cari user...</code>)</strong>: Cari pengguna berdasarkan <strong>Nama Lengkap</strong>, <strong>Alamat Email</strong>, atau <strong>Username</strong>.</li><li><strong>Filter Role (<code>Semua Role</code>)</strong>: Saring tampilan akun berdasarkan peran tertentu, misalnya hanya menampilkan akun <em>Wali Kelas</em>, <em>Bendahara</em>, atau <em>Super Admin</em>.</li><li><strong>Tombol Refresh (<code>Refresh</code>)</strong>: Memperbarui data tabel secara realtime dari server jika baru saja ada perubahan.</li></ul><hr><h2 id="_2-alur-tambah-user-baru" tabindex="-1">2. Alur Tambah User Baru <a class="header-anchor" href="#_2-alur-tambah-user-baru" aria-label="Permalink to &quot;2. Alur Tambah User Baru&quot;">​</a></h2><p>Ikuti langkah-langkah berikut untuk menambahkan pengguna baru secara manual:</p>',12)),(n(),l(o,null,{default:e(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Klik%20'%2B%20Tambah%20User'%22%5D%20--%3E%20B%5B%222.%20Isi%20Formulir%20Lengkap%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Pilih%20Role%20Akses%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Klik%20'Buat%20User'%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Akun%20Aktif%20%26%20Siap%20Login%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="langkah-langkah" tabindex="-1">Langkah-langkah: <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah:&quot;">​</a></h3><ol><li>Klik tombol <strong><code>+ Tambah User</code></strong> berwarna ungu di pojok kanan atas tabel.</li><li>Modal jendela <strong>Tambah User Baru</strong> akan muncul. Isi data berikut: <ul><li><strong>Nama Lengkap</strong> <em>(Wajib)</em>: Masukkan nama lengkap pengguna beserta gelar (misal: <code>Ahmad Fauzi, S.Pd</code>).</li><li><strong>Email</strong> <em>(Wajib)</em>: Masukkan email aktif (misal: <code>ahmad.fauzi@sekolah.sch.id</code>). Email ini berfungsi sebagai identitas pengiriman notifikasi dan pemulihan akun.</li><li><strong>Username</strong> <em>(Wajib)</em>: ID unik pengguna untuk login ke aplikasi (misal: <code>ahmadfauzi</code>). Tidak boleh menggunakan spasi.</li><li><strong>Password</strong> <em>(Wajib)</em>: Minimal 8 karakter. Disarankan perpaduan huruf dan angka (misal: <code>Sekolah2026!</code>).</li><li><strong>Konfirmasi Password</strong> <em>(Wajib)</em>: Ketik ulang password untuk memastikan tidak ada salah ketik.</li><li><strong>Role</strong> <em>(Wajib)</em>: Pilih salah satu peran dari dropdown (misal: <em>Administrator</em>, <em>Wali Kelas</em>, <em>Staff</em>, <em>Bendahara</em>).</li></ul></li><li>Klik tombol <strong><code>Buat User</code></strong>.</li><li>Sistem akan memvalidasi data. Jika sukses, notifikasi hijau akan muncul dan akun baru langsung masuk ke dalam daftar tabel.</li></ol><hr><h2 id="_3-alur-mengedit-data-user" tabindex="-1">3. Alur Mengedit Data User <a class="header-anchor" href="#_3-alur-mengedit-data-user" aria-label="Permalink to &quot;3. Alur Mengedit Data User&quot;">​</a></h2><p>Jika staf mengalami perubahan nama, pergantian email, atau promosi peran:</p><ol><li>Cari akun yang ingin diubah pada tabel pengguna.</li><li>Di kolom paling kanan (<strong>Aksi</strong>), klik tombol <strong>Ikon Edit (Pensil)</strong>.</li><li>Modal jendela <strong>Edit User</strong> akan terbuka dengan data yang sudah terisi otomatis: <ul><li>Anda dapat mengubah <strong>Nama Lengkap</strong>, <strong>Email</strong>, atau <strong>Role</strong>.</li><li><strong>Kolom Password</strong>: Pada mode edit, kolom password bersifat <strong>opsional</strong>. Jika Anda tidak ingin mengganti kata sandi pengguna, <strong>biarkan kolom password kosong</strong>.</li></ul></li><li>Klik tombol <strong><code>Update User</code></strong> untuk menyimpan perubahan.</li></ol><hr><h2 id="_4-alur-import-massal-user-via-excel" tabindex="-1">4. Alur Import Massal User via Excel <a class="header-anchor" href="#_4-alur-import-massal-user-via-excel" aria-label="Permalink to &quot;4. Alur Import Massal User via Excel&quot;">​</a></h2><p>Jika Anda perlu mendaftarkan puluhan atau ratusan akun guru/staf sekaligus di awal tahun ajaran baru, gunakan fitur <strong>Import Excel</strong>:</p>',9)),(n(),l(o,null,{default:e(()=>[s(r,{id:"mermaid-150",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%221.%20Klik%20'Import%20Excel'%22%5D%20--%3E%20B%5B%222.%20Unduh%20Template%20(.xlsx)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Isi%20Data%20Staf%20di%20Excel%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Unggah%20File%20ke%20Sistem%22%5D%0A%20%20%20%20D%20--%3E%20E%7B%22Pemeriksaan%20Sistem%22%7D%0A%20%20%20%20E%20--%3E%7CValid%7C%20F%5B%22Semua%20Akun%20Berhasil%20Dibuat%22%5D%0A%20%20%20%20E%20--%3E%7CAda%20Duplikat%7C%20G%5B%22Laporan%20Baris%20Error%20%26%20Rekap%20Sukses%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h3 id="langkah-langkah-detail" tabindex="-1">Langkah-langkah Detail: <a class="header-anchor" href="#langkah-langkah-detail" aria-label="Permalink to &quot;Langkah-langkah Detail:&quot;">​</a></h3><ol><li>Klik tombol <strong><code>Import Excel</code></strong> di atas tabel.</li><li>Pada modal yang muncul, klik tombol <strong><code>Unduh Template Excel</code></strong>.</li><li>Buka file template hasil unduhan di Microsoft Excel. <ul><li><strong>Struktur Kolom</strong>: <ul><li><code>name</code>: Nama lengkap pengguna.</li><li><code>email</code>: Alamat email unik (tidak boleh sama dengan pengguna lain).</li><li><code>username</code>: Username unik untuk login.</li><li><code>password</code>: Password default awal (minimal 8 karakter).</li><li><code>role</code>: Nama role persis sesuai sistem (misal: <code>guru</code>, <code>staff</code>, <code>bendahara</code>).</li></ul></li></ul></li><li>Simpan file yang telah diisi (format <code>.xlsx</code> atau <code>.xls</code>, ukuran maksimal 5 MB).</li><li>Tarik (<em>drag &amp; drop</em>) file ke area unggah atau klik <strong>Pilih File</strong> untuk mencari file di komputer Anda.</li><li>Klik tombol <strong><code>Proses Import</code></strong>.</li><li>Sistem akan memproses data dan menampilkan dialog rekapitulasi: <ul><li><strong>Jumlah Berhasil</strong>: Total akun yang sukses didaftarkan.</li><li><strong>Jumlah Gagal / Duplikat</strong>: Jika ada baris dengan email atau username yang sudah terdaftar sebelumnya, sistem akan menandai nomor baris tersebut agar dapat Anda perbaiki.</li></ul></li></ol><hr><h2 id="_5-alur-export-data-user-ke-excel" tabindex="-1">5. Alur Export Data User ke Excel <a class="header-anchor" href="#_5-alur-export-data-user-ke-excel" aria-label="Permalink to &quot;5. Alur Export Data User ke Excel&quot;">​</a></h2><p>Fitur ini berguna untuk membuat laporan arsip data kepegawaian atau rekap akun pengguna:</p><ol><li><em>(Opsional)</em> Terapkan filter terlebih dahulu jika Anda hanya ingin mengekspor kelompok tertentu (misal: filter Role = <em>Wali Kelas</em>).</li><li>Klik tombol <strong><code>Export Excel</code></strong> di atas tabel.</li><li>Sistem akan secara otomatis mengompilasi data dan mengunduh file spreadsheet <code>.xlsx</code> ke komputer Anda.</li><li>File unduhan memuat informasi: ID Pengguna, Nama Lengkap, Email, Username, Role, Status Akun, dan Tanggal Dibuat.</li></ol><hr><h2 id="_6-alur-menonaktifkan-menghapus-akun" tabindex="-1">6. Alur Menonaktifkan / Menghapus Akun <a class="header-anchor" href="#_6-alur-menonaktifkan-menghapus-akun" aria-label="Permalink to &quot;6. Alur Menonaktifkan / Menghapus Akun&quot;">​</a></h2><p>Jika staf atau guru sudah mutasi atau tidak lagi bertugas di sekolah:</p><ol><li>Pada tabel pengguna, centang kotak di samping nama akun yang bersangkutan, atau klik tombol <strong>Hapus (Ikon Tempat Sampah)</strong> pada baris user.</li><li>Jendela konfirmasi keamanan <strong>Hapus User</strong> akan muncul: <ul><li>Terdapat peringatan dampak penghapusan akun.</li></ul></li><li>Klik tombol merah <strong><code>Ya, Hapus User</code></strong>.</li><li>Akun tersebut tidak lagi dapat digunakan untuk masuk (<em>login</em>) ke portal sekolah.</li></ol><div class="tip custom-block"><p class="custom-block-title">Tips Keamanan Akun</p><p>Sebaiknya jangan memberikan role <strong>Super Admin</strong> kepada staf biasa. Berikan role sesuai tugas pokok fungsinya (misal: TU cukup role <em>Staff</em>, guru pengajar role <em>Guru</em>, bendahara role <em>Bendahara</em>) agar hak akses sistem tetap tertib dan aman.</p></div>',11))])}const E=u(k,[["render",p]]);export{x as __pageData,E as default};
